{"code": "async (page) => {
  // Scroll to load all results
  for (let i = 0; i < 10; i++) {
    await page.evaluate(() => window.scrollBy(0, window.innerHeight));
    await page.waitForTimeout(300);
  }
  // Extract all text from search results
  const text = await page.evaluate(() => {
    // Select the main search results container
    const main = document.querySelector('div#search') || document.body;
    return main.innerText;
  });
  return text;
}"}

{"code": "async (page) => {
  // Extract AI Overview text if present
  const aiText = await page.evaluate(() => {
    // Look for elements containing "AI Overview"
    const aiSection = Array.from(document.querySelectorAll('*')).find(el => el.innerText.includes('AI Overview'));
    if (aiSection) {
      // Get the parent container and extract text
      let container = aiSection.closest('div') || aiSection.parentElement;
      // Try to get the next sibling that contains bullet points
      return container.innerText;
    }
    return null;
  });
  // Also extract all search result snippets
  const snippets = await page.evaluate(() => {
    const results = Array.from(document.querySelectorAll('div.g, div.yuRUbf, div.VwiC3b'));
    return results.map(r => r.innerText).filter(t => t.length > 20);
  });
  return { aiText, snippets: snippets.slice(0, 10) };
}"}

{"code": "async (page) => {
  // Find the AI Overview section by heading text
  const aiOverview = await page.evaluate(() => {
    const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4, h5, h6, div, span'));
    const aiHeading = headings.find(el => el.innerText && el.innerText.includes('AI Overview'));
    if (aiHeading) {
      // Find the parent container that holds the content
      let parent = aiHeading.closest('div') || aiHeading.parentElement;
      // Walk up until we find a container with substantial content
      while (parent && parent.children.length < 2 && parent.innerText.length < 500) {
        parent = parent.parentElement;
      }
      return parent ? parent.innerText : aiHeading.innerText;
    }
    return null;
  });
  return aiOverview;
}"}

